// Counts primes below 1,000,000,000 using Lucy_Hedgehog's O(n^(3/4)) method.
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

int main(int argc, char **argv) {
    int64_t n = argc > 1 ? atoll(argv[1]) - 1 : 999999999; // count primes <= n
    int64_t r = (int64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    int64_t *lo = malloc((r + 2) * sizeof *lo); // lo[v]: count for v
    int64_t *hi = malloc((r + 2) * sizeof *hi); // hi[i]: count for n/i
    for (int64_t i = 1; i <= r; i++) {
        lo[i] = i - 1;
        hi[i] = n / i - 1;
    }
    lo[0] = 0;

    for (int64_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue; // p not prime
        int64_t pc = lo[p - 1], p2 = p * p;
        int64_t end = n / p2 < r ? n / p2 : r;
        for (int64_t i = 1; i <= end; i++) {
            int64_t d = i * p;
            hi[i] -= (d <= r ? hi[d] : lo[n / d]) - pc;
        }
        for (int64_t v = r; v >= p2; v--)
            lo[v] -= lo[v / p] - pc;
    }
    printf("%lld\n", (long long)hi[1]);
    return 0;
}
