<parameter name="content">use std::sync::atomic::{AtomicUsize, Ordering};
use std::thread;

const N: usize = 1_000_000_000;
const SEG: usize = 32 * 1024; // odd-number slots per segment (fits L1)
const SEGS_PER_CHUNK: usize = 64;

fn small_primes(limit: usize) -> Vec<u32> {
    let mut s = vec![true; limit + 1];
    let mut v = Vec::new();
    for i in 2..=limit {
        if s[i] {
            if i > 2 {
                v.push(i as u32);
            }
            let mut j = i * i;
            while j <= limit {
                s[j] = false;
                j += i;
            }
        }
    }
    v
}

fn main() {
    // Slot i represents the odd number 2i+1; slots cover odd numbers < N.
    let total_slots = N / 2;
    let root = (N as f64).sqrt() as usize + 1;
    let primes = small_primes(root);

    let chunk_slots = SEG * SEGS_PER_CHUNK;
    let nchunks = (total_slots + chunk_slots - 1) / chunk_slots;
    let next_chunk = AtomicUsize::new(0);
    let nthreads = thread::available_parallelism().map(|n| n.get()).unwrap_or(1);

    let count: usize = thread::scope(|sc| {
        let hs: Vec<_> = (0..nthreads)
            .map(|_| {
                sc.spawn(|| {
                    let mut seg = vec![0u8; SEG];
                    let mut next = vec![0usize; primes.len()];
                    let mut local = 0usize;
                    loop {
                        let c = next_chunk.fetch_add(1, Ordering::Relaxed);
                        if c >= nchunks {
                            break;
                        }
                        let c_lo = c * chunk_slots;
                        let c_hi = (c_lo + chunk_slots).min(total_slots);

                        // Initialise per-prime start offsets for this chunk.
                        let first_odd = 2 * c_lo + 1;
                        for (k, &p) in primes.iter().enumerate() {
                            let p = p as usize;
                            let sq = p * p;
                            next[k] = if sq >= first_odd {
                                (sq - 1) / 2
                            } else {
                                let mut m = (first_odd + p - 1) / p * p;
                                if m % 2 == 0 {
                                    m += p;
                                }
                                (m - 1) / 2
                            };
                        }

                        let mut lo = c_lo;
                        while lo < c_hi {
                            let hi = (lo + SEG).min(c_hi);
                            let len = hi - lo;
                            seg[..len].fill(0);
                            for (k, &p) in primes.iter().enumerate() {
                                let p = p as usize;
                                let mut j = next[k];
                                if j >= hi {
                                    continue;
                                }
                                j -= lo;
                                while j < len {
                                    unsafe { *seg.get_unchecked_mut(j) = 1 };
                                    j += p;
                                }
                                next[k] = j + lo;
                            }
                            local += seg[..len].iter().map(|&b| (b == 0) as u32 as usize).sum::<usize>();
                            lo = hi;
                        }
                    }
                    local
                })
            })
            .collect();
        hs.into_iter().map(|h| h.join().unwrap()).sum()
    });

    // Remove slot 0 (the number 1), add the prime 2.
    println!("{}", count - 1 + 1);
}
