// Count primes below 1e9: odd-only bit-packed segmented sieve, L1-sized segments, OpenMP.
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define N         1000000000ULL
#define TOTAL     (N / 2)            // bit i represents the number 2i+1
#define SEG_BITS  (1u << 18)         // 32 KB per segment
#define SEG_WORDS (SEG_BITS / 64)
#define SQRT_N    31623

int main(void) {
    static uint32_t primes[4000];
    int np = 0;
    static char comp[SQRT_N + 1];
    for (uint32_t i = 2; i <= SQRT_N; i++) {
        if (comp[i]) continue;
        if (i > 2) primes[np++] = i;
        for (uint32_t j = i * i; j <= SQRT_N; j += i) comp[j] = 1;
    }

    uint64_t nseg = (TOTAL + SEG_BITS - 1) / SEG_BITS;
    uint64_t count = 1;              // the prime 2

    #pragma omp parallel for schedule(dynamic, 4) reduction(+:count)
    for (uint64_t s = 0; s < nseg; s++) {
        uint64_t seg[SEG_WORDS];
        memset(seg, 0, sizeof seg);
        uint64_t lo = s * SEG_BITS;
        uint64_t hi = lo + SEG_BITS < TOTAL ? lo + SEG_BITS : TOTAL;

        for (int k = 0; k < np; k++) {
            uint64_t p = primes[k];
            uint64_t i = (p * p - 1) / 2;
            if (i >= hi) break;
            if (i < lo) i = lo + ((p - 1) / 2 + p - lo % p) % p;
            for (i -= lo; i < hi - lo; i += p)
                seg[i >> 6] |= 1ULL << (i & 63);
        }
        if (s == 0) seg[0] |= 1;     // number 1 is not prime

        uint64_t len = hi - lo;
        for (uint64_t b = len; b < SEG_BITS; b++)   // only runs for the last segment
            seg[b >> 6] |= 1ULL << (b & 63);

        uint64_t c = 0;
        for (int w = 0; w < SEG_WORDS; w++) c += __builtin_popcountll(~seg[w]);
        count += c;
    }

    printf("%llu\n", (unsigned long long)count);
    return 0;
}
